<template><section class="note-editor"><header><div><h2>Note · 编辑笔记</h2><small>{{ dirty?'有未保存的修改':'笔记已载入' }}</small></div><div><button @click="close">关闭</button><button class="primary" :disabled="busy" @click="save">{{ busy?'保存中…':'保存笔记' }}</button></div></header><input class="note-title" v-model="title" @input="dirty=true" aria-label="笔记标题" maxlength="200"/><div class="note-toolbar" @mousedown.prevent><button @click="format('formatBlock','h1')">H1</button><button @click="format('formatBlock','h2')">H2</button><button @click="format('bold')"><b>B</b></button><button @click="format('italic')"><i>I</i></button><button @click="format('insertUnorderedList')">• 列表</button><button @click="insertLink">链接</button><button @click="chooseImage">▧ 插入图片</button><input ref="file" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="upload"/></div><div ref="editor" contenteditable="true" role="textbox" aria-label="笔记正文" aria-multiline="true" class="note-body" @input="dirty=true" @paste="paste" @drop.prevent></div><p v-if="error" role="alert" class="error">{{ error }}</p><footer>笔记独立保存，编辑不会修改原报告。支持 PNG、JPEG、WebP 图片，单张不超过 3 MB。</footer></section></template>
<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {api} from '../services/api';import {noteHTML,type PersonalNote} from '../services/notes';
const props=defineProps<{note:PersonalNote;initialDirty?:boolean}>();const emit=defineEmits<{saved:[note:PersonalNote];close:[]}>();const title=ref(props.note.title);const editor=ref<HTMLElement|null>(null);const file=ref<HTMLInputElement|null>(null);const dirty=ref(!!props.initialDirty||!props.note.id);const busy=ref(false);const error=ref('');let range:Range|null=null;
onMounted(()=>{if(editor.value)editor.value.innerHTML=noteHTML(props.note.html);window.addEventListener('beforeunload',beforeUnload)});onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue='';}}
function allowClose(){return !dirty.value||window.confirm('笔记尚未保存，确定放弃修改并关闭？');}function snapshot(){return {note:{...props.note,title:title.value,html:noteHTML(editor.value?.innerHTML||'')},dirty:dirty.value};}defineExpose({allowClose,snapshot});function close(){if(allowClose())emit('close');}
function format(command:string,value=''){editor.value?.focus();document.execCommand(command,false,value);dirty.value=true;}
function insertLink(){const url=window.prompt('链接地址（https://…）');if(url&&/^https?:\/\//i.test(url))format('createLink',url);}
function chooseImage(){const s=window.getSelection();range=s?.rangeCount?s.getRangeAt(0).cloneRange():null;file.value?.click();}
async function insertImage(f:File){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>3*1024*1024){error.value='请选择不超过 3 MB 的 PNG、JPEG 或 WebP 图片';return}const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(f)});editor.value?.focus();if(range&&editor.value?.contains(range.commonAncestorContainer)){const s=window.getSelection();s?.removeAllRanges();s?.addRange(range)}format('insertImage',data);error.value='';}
async function upload(e:Event){const input=e.target as HTMLInputElement;const f=input.files?.[0];if(f)try{await insertImage(f)}catch{error.value='图片读取失败'}input.value='';}
function paste(e:ClipboardEvent){e.preventDefault();const image=Array.from(e.clipboardData?.files||[]).find(f=>f.type.startsWith('image/'));if(image){void insertImage(image);return}const html=e.clipboardData?.getData('text/html');if(html)format('insertHTML',noteHTML(html));else format('insertText',e.clipboardData?.getData('text/plain')||'');}
async function save(){if(!title.value.trim()){error.value='请填写笔记标题';return}busy.value=true;error.value='';try{const html=noteHTML(editor.value?.innerHTML||'');const note=await api<PersonalNote>(`/notes${props.note.id?'/'+props.note.id:''}`,{method:props.note.id?'PUT':'POST',body:JSON.stringify({title:title.value.trim(),html,run_id:props.note.run_id||null})});dirty.value=false;emit('saved',note);}catch(e){error.value=e instanceof Error?e.message:'保存失败';}finally{busy.value=false;}}
</script>
<style scoped>.note-editor{background:white;padding:24px;min-height:100%;box-sizing:border-box;color:#24334d}.note-editor header{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;margin-bottom:20px;gap:12px}.note-editor h2{font-size:20px;margin:0 0 5px}.note-editor small{color:#8997ad}.note-editor button{border:1px solid #d4dff0;border-radius:7px;padding:8px 12px;background:white;color:#426699;cursor:pointer;margin-right:5px}.note-editor .primary{background:#3775ff;color:white}.note-title{width:100%;box-sizing:border-box;padding:12px;border:1px solid #d4dff0;border-radius:8px;font-size:18px;font-weight:600}.note-toolbar{display:flex;gap:4px;flex-wrap:wrap;margin-top:18px;padding:8px;border:1px solid #dce5f2;background:#f7faff}.note-body{min-height:420px;border:1px solid #dce5f2;border-top:0;padding:20px;line-height:1.85;outline:none;overflow-wrap:anywhere}.note-body:focus{border-color:#89afff}.note-body :deep(img){max-width:100%;height:auto}.note-body :deep(table){border-collapse:collapse;max-width:100%}.note-body :deep(td),.note-body :deep(th){border:1px solid #dce5f2;padding:8px}.error{color:#b73c4a;font-size:13px}footer{color:#8592a8;font-size:12px;margin-top:18px}</style>
